# META "creator" "Don Brutzman"
# META "created" "24 May 2000"
# META "modified" "28 October 2019"
# META "creator" "X3D working group"
# META "description" "VRML 97 specification example: This Script node decides whether or not to open a bank vault given openVault and combinationEntered messages. To do this, it remembers whether or not the correct combination has been entered. The Script node combined with a Sphere, a TouchSensor and a Sound node to show how is works. When the pointing device is over the sphere, the combinationEntered eventIn of the Script is sent. Then, when the Sphere is touched (typically when the mouse button is pressed) the Script is sent the openVault eventIn. This generates the vaultUnlocked eventOut which starts a 'click' sound."
# META "specificationUrl" "originals/exampleD_5.wrl"
# META "specificationSection" "VRML 97, ISO/IEC 14772-1, Part 1: Functional specification and UTF-8 encoding, D.5 Scripting example"
# META "specificationUrl" "https://www.web3d.org/documents/specifications/14772/V2.0/part1/examples.html#D.5"
# META "identifier" "https://www.web3d.org/x3d/content/examples/Basic/Vrml97Specification/Example05.x3d"
# META "generator" "X3D-Edit 3.3, https://www.web3d.org/x3d/tools/X3D-Edit"
# META "license" "../license.html"

# [Scene] ========== ========== ==========
# Warning: VRML97-style scripting, not X3D Scene Authoring Interface (SAI)
WorldInfo {
  title "Example05.x3d"
}
DEF OpenVault Script {
  # field tags are declarations of what interfaces are in this Script node
  eventIn      SFTime	 openVault
  eventIn      SFBool	 combinationEntered
  eventOut     SFTime	 vaultUnlocked
  field        SFBool	 unlocked FALSE
  # field tags are declarations of what interfaces are in this Script node

	url [ "javascript:
function combinationEntered (value)
{
	unlocked = value;
}
function openVault(value)
{
	if (unlocked) vaultUnlocked = value;
}


" ]
}
Shape {
  appearance Appearance {
    material Material {
      diffuseColor 1 0 0
    }
  }
  geometry Sphere {
  }
}
Sound {
  maxBack 1000
  maxFront 1000
  minBack 1000
  minFront 1000
  source DEF Click AudioClip {
    description "click"
    stopTime 1
    url [ "click.wav" "https://www.web3d.org/x3d/content/examples/Basic/Vrml97Specification/click.wav" ]
  }
}
DEF TS TouchSensor {
   # description "touch ball to hear a click"
}
ROUTE TS.isOver TO OpenVault.combinationEntered
ROUTE TS.touchTime TO OpenVault.openVault
ROUTE OpenVault.vaultUnlocked TO Click.startTime

