                                                        translation 0.0 0.075 0.0
                                                        children [
                                                                                                                  Shape {
                                                              appearance USE Red
                                                              geometry Cone {
                                                                bottom FALSE
                                                                bottomRadius 0.12
                                                                height 0.15
                                                              }
                                                            }
                                                            Transform {
                                                              translation 0.0 0.075 0.0
                                                              children [
                                                                                                                              DEF LightSwitch TouchSensor {
                                                                     # description "Click to toggle light on/off"
                                                                  }
                                                                  Shape {
                                                                    appearance Appearance {
                                                                      material Material {
                                                                        diffuseColor 1.0 1.0 1.0
                                                                      }
                                                                    }
