ROUTE MoveLamp.translation_changed TO Lamp.set_translation
ROUTE MoveFirstArm.rotation_changed TO FirstArm.set_rotation
ROUTE MoveSecondArm.rotation_changed TO SecondArm.set_rotation
ROUTE MoveLampShade.rotation_changed TO LampShade.set_rotation
DEF Toggle Script {
  field        SFBool	 on TRUE
  eventIn      SFBool	 set_active
  eventOut     SFBool	 on_changed

	url [ "javascript:
		function set_active( b, tm ) {
			// ignore button releases
			if ( b == false ) return;

			// toggle on button presses
			if ( on == true ) on = false;
			else              on = true;
			on_changed = on;
		}


" ]
}
DEF ColorSelector Script {
  field        SFColor	 offColor 0.0 0.0 0.0
  field        SFColor	 onColor 1.0 1.0 1.0
  eventOut     SFColor	 color_changed
  eventIn      SFBool	 set_selection

	url [ "javascript:
		function set_selection( b, tm ) {
			if ( b == true )
				color_changed = onColor;
			else
				color_changed = offColor;
		}


" ]
}
ROUTE LightSwitch.isActive TO Toggle.set_active
ROUTE Toggle.on_changed TO LampLight.set_on
ROUTE Toggle.on_changed TO ColorSelector.set_selection
ROUTE ColorSelector.color_changed TO BulbMaterial.set_emissiveColor

